def center(text, size=14, bold=False, before=0, after=8, style=None):
    q=doc.add_paragraph(style=style)
    q.alignment=WD_ALIGN_PARAGRAPH.CENTER
    q.paragraph_format.first_line_indent=Cm(0)
    q.paragraph_format.space_before=Pt(before)
    q.paragraph_format.space_after=Pt(after)
    r=q.add_run(text); r.bold=bold; r.font.size=Pt(size)
    return q


